INSERT INTO missions(id, code, name, description, category, sequence) VALUES(1,'mission-001-first-starter','Mission 1 - Obtain the first shiny starter','Starts the game, completes Littleroot events, and obtains the configured shiny starter.','main_story',1);
INSERT INTO missions(id, code, name, description, category, sequence) VALUES(2,'mission-002-first-poke-balls','Mission 2 - Receive the first Poké Balls','Defeats the rival on Route 103 and receives the Pokédex and first Poké Balls.','main_story',2);
INSERT INTO missions(id, code, name, description, category, sequence) VALUES(3,'mission-003-reach-route102','Mission 3 - Reach the first route','Reaches Route 102, makes the first capture, and forms the initial party.','main_story',3);
INSERT INTO missions(id, code, name, description, category, sequence) VALUES(4,'mission-004-stone-badge','Mission 4 - Stone Badge','Petalburg, Petalburg Woods, Rustboro, and Stone Badge.','main_story',4);
INSERT INTO missions(id, code, name, description, category, sequence) VALUES(5,'mission-005-dynamo-badge','Mission 5 - Dynamo Badge','Devon Goods, Dewford, Slateport, and Dynamo Badge.','main_story',5);
INSERT INTO missions(id, code, name, description, category, sequence) VALUES(6,'mission-006-balance-badge','Mission 6 - Balance Badge','Meteor Falls, Mt. Chimney, Lavaridge, and Balance Badge.','main_story',6);
INSERT INTO missions(id, code, name, description, category, sequence) VALUES(7,'mission-007-feather-badge','Mission 7 - Feather Badge','Weather Institute, Devon Scope, Fortree, and Feather Badge.','main_story',7);
INSERT INTO missions(id, code, name, description, category, sequence) VALUES(8,'mission-008-mind-badge','Mission 8 - Mind Badge','Mt. Pyre, Magma/Aqua bases, Mossdeep, and Mind Badge.','main_story',8);
INSERT INTO missions(id, code, name, description, category, sequence) VALUES(9,'mission-009-rain-badge','Mission 9 - Rain Badge','Seafloor Cavern, main legendary, Sootopolis, and Rain Badge.','main_story',9);
INSERT INTO missions(id, code, name, description, category, sequence) VALUES(10,'mission-010-champion','Mission 10 - Champion','Victory Road, Elite Four, and Champion.','main_story',10);
